                        src_fifo[0] <= src_data_i;
                        src_wptr <= 2'b00;
                        src_depth <= 2'b01;
                        src_fsm <= 2'b01;
                        src_ready_o <= 1'b0;
                    end else begin
                        src_ready_o <= 1'b1;
                    end
