                default: begin
                    dst_fsm <= 2'b00;
                    dst_depth <= 2'b00;
                    dst_rptr <= 2'b00;
                    dst_fifo <= 1'b0;
                    dst_valid_o <= 1'b0;
                    dst_data_o <= 1'b0;
                end
            endcase
        end
    end

    // Output data selection
    assign dst_data_o = (dst_fsm == 2'b01) ? dst_fifo[0] : dst_fifo[1];

